import * as U from '../ui.js';import {readImportFile} from '../import-file-reader.js';import {draftRow,validateDraft,WEEKDAYS,parsePlainText} from '../import-parser.js';import {buildImport,validateImportOptions} from '../import-builder.js';
const end=new Date(U.TODAY+'T12:00Z');end.setUTCDate(end.getUTCDate()+120);
let state={phase:'upload',files:[],rows:[],preview:null,text:'',message:'',progress:0,status:'',language:'eng+ara',reviewed:false,stats:null,saved:false};let job=0,cancelRecognition=null;
const options={semester:U.db.courses[0]?.semester||'My semester',start:U.TODAY,end:end.toISOString().slice(0,10),timezone:U.db.users[0].timezone};
const field=(row,key,label,type='text')=>`<label class="field"><span>${label}</span><input type="${type}" data-entry="${row.id}" data-key="${key}" value="${U.esc(row[key]||'')}" ${key==='name'?'maxlength="160"':''}></label>`;
function entry(row,index){const issues=row.include?validateDraft(row):[],existing=U.db.courses.some(c=>(row.course_code?c.course_code?.toLowerCase()===row.course_code.toLowerCase():c.name.toLowerCase()===row.name.toLowerCase())&&c.semester===options.semester);return `<article class="card import-entry ${!row.include?'excluded':''}" data-entry-card="${row.id}"><header class="import-entry-header"><label><input type="checkbox" data-entry="${row.id}" data-key="include" ${row.include?'checked':''}>Entry ${index+1}</label>${U.tag(!row.include?'Excluded':issues.length?'Check details':row.warnings?.length?'Check extraction':existing?'Existing subject':'Ready',!row.include?'':issues.length||row.warnings?.length?'warn':'green')}</header><p class="import-source">${U.esc(row.source||'Added entry')}</p>${row.warnings?.length?`<p class="note warn" role="note">${row.warnings.map(U.esc).join(' ')}</p>`:''}<div class="form-grid">${field(row,'course_code','Course code')}${field(row,'name','Subject name *')}<label class="field full"><span>Import as</span><select data-entry="${row.id}" data-key="has_schedule"><option value="true" ${row.has_schedule?'selected':''}>Subject and weekly class</option><option value="false" ${!row.has_schedule?'selected':''}>Subject only</option></select></label>${row.has_schedule?`<label class="field"><span>Day *</span><select data-entry="${row.id}" data-key="weekday"><option value="">Choose day</option>${WEEKDAYS.map((d,i)=>`<option value="${i+1}" ${Number(row.weekday)===i+1?'selected':''}>${d[0]}</option>`).join('')}</select></label><label class="field"><span>Class type *</span><select data-entry="${row.id}" data-key="title"><option value="">Choose type</option>${['Lecture','Section','Lab','Tutorial','Other'].map(t=>`<option ${t===row.title?'selected':''}>${t}</option>`).join('')}</select></label>${field(row,'starts_at_local','Start time *','time')}${field(row,'ends_at_local','End time *','time')}${field(row,'room','Room')}${field(row,'building','Building (optional)')}`:''}</div>${issues.length?`<p class="import-entry-error">${issues.map(U.esc).join(' · ')}</p>`:''}</article>`}
const update=U.mount(()=>{const busy=state.phase==='reading'||state.phase==='saving';if(state.phase==='done')return U.heading('YOUR TIMETABLE IS READY','Import complete.','Your file entries are saved to your account.')+`<section class="card booking-success"><div class="success-symbol">${U.icon('check')}</div><h2>${state.saved?'Your schedule is ready.':'Saved on this device.'}</h2><div class="study-summary"><div><strong>${state.stats.courses}</strong><span>new subjects</span></div><div><strong>${state.stats.schedules}</strong><span>weekly classes</span></div><div><strong>${state.stats.sessions}</strong><span>dated classes</span></div><div><strong>${state.stats.duplicates}</strong><span>duplicates skipped</span></div></div>${state.message?`<div class="note warn">${U.esc(state.message)}</div>`:''}<div class="actions confirmation-actions"><a class="btn primary" href="schedule.html">View schedule →</a><a class="btn" href="courses.html">View subjects</a>${!state.saved?'<button class="btn" id="retry-import-sync">Retry saving to account</button>':''}<button class="btn" id="another-file">Import another file</button></div></section>`;
return U.heading('LESS TYPING, MORE CLARITY','Import your timetable.','Upload a screenshot or PDF. Review the subjects and times, then save.','<a class="btn" href="schedule.html">Back to schedule →</a>')+`<ol class="import-steps" aria-label="Import progress"><li class="${state.phase==='upload'?'active':''}"><span>1</span>Upload</li><li class="${state.phase==='review'?'active':''}"><span>2</span>Review</li><li><span>3</span>Save to account</li></ol>${state.message?`<div class="booking-error-summary" role="alert">${U.esc(state.message)}</div>`:''}<section class="card import-upload"><div class="import-upload-main"><div class="course-symbol">${U.icon('calendar')}</div><h2>${state.files.length?state.files.map(f=>U.esc(f.name)).join(', '):'Your timetable, without the typing.'}</h2><p>Choose a clear screenshot, photo, or PDF. Keep the weekday labels and all class times visible.</p><label class="btn primary import-file-label" for="timetable-files" role="button" tabindex="0">${U.icon('plus')}${state.files.length?'Choose another file':'Choose files'}</label><input class="visually-hidden" id="timetable-files" type="file" accept=".png,.jpg,.jpeg,.webp,.pdf,.csv,.tsv,.txt" multiple ${busy?'disabled':''}><small>PNG, JPG, WebP, PDF, CSV · Up to 15 MB per file · Up to 5 files</small></div><div class="import-upload-options"><label class="field"><span>Text recognition language</span><select id="import-language" ${busy?'disabled':''}><option value="eng" ${state.language==='eng'?'selected':''}>English</option><option value="eng+ara" ${state.language==='eng+ara'?'selected':''}>English + Arabic</option></select></label><p class="small muted">Files are read on your device. Only the subjects and classes you confirm are saved.</p><a class="text-link" href="/timetable-template.csv" download>Download a CSV template ↓</a></div></section>${state.phase==='reading'?`<section class="card import-progress" role="status" aria-live="polite"><h2>${U.esc(state.status||'Reading your file…')}</h2><div class="progress"><i style="width:${state.progress}%"></i></div><p class="small muted">Text recognition may take a little time, especially for photos and scanned PDFs.</p><button class="btn" id="cancel-import">Cancel</button></section>`:''}${state.phase==='review'||state.phase==='saving'?`<section class="card import-semester"><div class="section-head"><div><h2>Where do these classes belong?</h2><p>Dates are not always in a timetable image. Confirm your semester and timezone.</p></div></div><div class="form-grid"><label class="field"><span>Semester name *</span><input data-import-option="semester" value="${U.esc(options.semester)}"></label><label class="field"><span>Timezone *</span><input data-import-option="timezone" value="${U.esc(options.timezone)}"></label><label class="field"><span>First day *</span><input type="date" data-import-option="start" value="${options.start}"></label><label class="field"><span>Last day *</span><input type="date" data-import-option="end" value="${options.end}"></label></div></section><div class="toolbar"><div><h2>Check the detected entries</h2><p class="small muted" style="margin-top:7px">${state.rows.filter(r=>r.include).length} selected · ${state.rows.filter(r=>r.include&&validateDraft(r).length).length} need attention</p></div><button class="btn" id="add-import-row">${U.icon('plus')}Add a missing entry</button></div>${!state.rows.length?'<div class="note warn" style="margin-bottom:20px">No subject codes could be detected. Try a clearer crop with course codes visible, or use the extracted text below to recover entries.</div>':''}<div class="import-entry-grid">${state.rows.map(entry).join('')}</div><details class="card import-original"><summary>Compare with the source file</summary>${state.preview?`<img src="${state.preview}" alt="Uploaded timetable source for review">`:''}<label class="field"><span>Extracted text</span><textarea id="import-extracted-text">${U.esc(state.text)}</textarea></label><button class="btn" id="parse-extracted-text">Read entries from this text</button></details><section class="card import-confirm"><label><input type="checkbox" id="import-reviewed" ${state.reviewed?'checked':''} ${busy?'disabled':''}><span>I checked the subject names, days, and times against my file.</span></label><p class="small muted">Existing subjects are kept. Identical classes are skipped. New subjects receive their own colors.</p><button id="save-import" class="btn primary" ${busy?'disabled':''}>${state.phase==='saving'?'Saving…':'Import selected entries'} ${U.icon('arrow')}</button></section>`:''}`});
async function readFiles(files){if(files.length>5){state.message='Choose up to 5 files at a time.';update();return}if(files.reduce((n,f)=>n+f.size,0)>31457280){state.message='Choose files totaling up to 30 MB.';update();return}const current=++job;state={...state,files,phase:'reading',message:'',rows:[],text:'',preview:null,reviewed:false,stats:null,progress:0,status:'Opening files…'};update();try{for(let index=0;index<files.length;index++){const file=files[index],result=await readImportFile(file,{language:state.language,cancelled:()=>current!==job,onCancel:fn=>cancelRecognition=fn,progress:(text,progress)=>{if(current!==job)return;state.status=text;state.progress=progress;const card=document.querySelector('.import-progress');if(card){card.querySelector('h2').textContent=text;card.querySelector('.progress i').style.width=progress+'%'}}});if(current!==job)return;state.rows.push(...result.rows);state.text+=(state.text?'\n\n':'')+result.text;if(!state.preview&&result.preview)state.preview=result.preview;if(state.rows.length>300)throw Error('More than 300 entries were detected. Import fewer pages at a time.')}state.phase='review';state.message='';update()}catch(error){if(current!==job)return;state.phase=state.rows.length?'review':'upload';state.message=error.message||'Could not read this file. Try a clearer image or a different PDF.';update()}finally{cancelRecognition=null}}
document.addEventListener('change',event=>{const target=event.target;if(target.id==='timetable-files'&&target.files.length)void readFiles([...target.files]);if(target.id==='import-language')state.language=target.value;if(target.id==='import-reviewed')state.reviewed=target.checked;if(target.dataset.importOption)options[target.dataset.importOption]=target.value;if(target.dataset.entry){const row=state.rows.find(r=>r.id===target.dataset.entry);if(!row)return;row.warnings=[];row[target.dataset.key]=target.dataset.key==='include'?target.checked:target.dataset.key==='has_schedule'?target.value==='true':target.dataset.key==='weekday'?(target.value?Number(target.value):null):target.value;state.reviewed=false;update()}});
document.addEventListener('input',event=>{const target=event.target;if(target.dataset.entry&&target.type!=='checkbox'&&target.tagName!=='SELECT'){const row=state.rows.find(r=>r.id===target.dataset.entry);if(row){row[target.dataset.key]=target.value;row.warnings=[]};state.reviewed=false;const checked=document.querySelector('#import-reviewed');if(checked)checked.checked=false}if(target.dataset.importOption){options[target.dataset.importOption]=target.value;state.reviewed=false;const checked=document.querySelector('#import-reviewed');if(checked)checked.checked=false}});
document.addEventListener('dragover',event=>{if(event.target.closest('.import-upload'))event.preventDefault()});document.addEventListener('drop',event=>{if(!event.target.closest('.import-upload'))return;event.preventDefault();if(state.phase!=='reading'&&state.phase!=='saving'&&event.dataTransfer.files.length)void readFiles([...event.dataTransfer.files])});
document.addEventListener('click',async event=>{if(event.target.closest('#cancel-import')){job++;try{await cancelRecognition?.()}catch{}state.phase='upload';state.message='Import cancelled. Nothing was saved.';update()}if(event.target.closest('#add-import-row')){state.rows.push(draftRow({has_schedule:true}));state.reviewed=false;update()}if(event.target.closest('#parse-extracted-text')){const text=document.querySelector('#import-extracted-text').value;const recovered=parsePlainText(text,'Edited source text');if(!recovered.length){U.toast('No course codes were found. Include a code such as BIO101.');return}state.rows=recovered;state.text=text;state.reviewed=false;update()}if(event.target.closest('#another-file')){state={...state,phase:'upload',rows:[],files:[],text:'',preview:null,stats:null,message:'',reviewed:false};update()}if(event.target.closest('#retry-import-sync')){state.saved=await U.flushWorkspace();state.message=state.saved?'':'Your changes are still saved on this device. Reconnect to the server and retry.';update()}if(event.target.closest('#save-import')){state.message='';if(!state.reviewed){state.message='Check the entries, then tick the review checkbox before importing.';update();return}const problem=validateImportOptions(options);if(problem){state.message=problem;update();return}try{const result=buildImport(U.db,state.rows,options,{today:U.TODAY});state.phase='saving';update();for(const [key,value] of Object.entries(result.workspace))U.db[key]=value;U.save();state.saved=await U.flushWorkspace();state.stats=result.stats;state.phase='done';state.message=state.saved?'':'Your import is saved on this device, but could not reach the server. Retry saving to your account.';update();window.scrollTo({top:0,behavior:'smooth'})}catch(error){state.phase='review';state.message=error.message;update();document.querySelector('[role="alert"]')?.scrollIntoView({block:'center',behavior:'smooth'})}}});

document.addEventListener('keydown',event=>{if(event.target.matches('.import-file-label')&&['Enter',' '].includes(event.key)){event.preventDefault();document.querySelector('#timetable-files').click()}});
